assets.styles.css:
html[data-surface-scene-layout="chat-thread"] .scs .scroll { background-image: none !important; }
html[data-surface-scene-layout="chat-thread"] .scs .bgm { background: radial-gradient(circle at 15% 20%, color-mix(in srgb, var(--bk-role-brand) 22%, transparent), transparent 38%), radial-gradient(circle at 85% 65%, color-mix(in srgb, var(--bk-role-info) 24%, transparent), transparent 42%), var(--bk-surface-well); }
html[data-surface-scene-message="bubble"] .scs .msg:not(.user) .bub { border-left: 4px solid var(--bk-role-brand-deep); }
html[data-surface-scene-message="bubble"] .scs .msg.user .bub { border-left: 4px solid var(--bk-role-action-deep); }


/* Prismatic navigation paint on Bunzai's persistent bottom dock. */
[data-part="shell.nav"] nav { background: #281a3b; border-color: #785e88; }
[data-part="shell.nav.tile"] { color: #fff8f5; }
[data-part="shell.nav.tile"]:hover { background: #48305d; }
[data-part="shell.nav.tile"][aria-current="page"] { background: var(--bk-role-brand); color: #281a3b; }
/* Sticker cards keep their artwork, with a light label and dark readable ink. */
html[data-surface-library-card="sticker-card"] .lib.rc .rcard {
  --stage-card: #241a22;
  --stage-soft: #3c2b38;
  --stage-text-dim: #514051;
}
html[data-surface-library-card="sticker-card"] .lib.rc .rcbody,
html[data-surface-library-card="sticker-card"] .lib.rc .rahead,
html[data-surface-library-card="sticker-card"] .lib.rc .rpbody,
html[data-surface-library-card="sticker-card"] .lib.rc .rrbody,
html[data-surface-library-card="sticker-card"] .lib.rc .rabody {
  background: var(--bk-surface-panel);
  color: var(--bk-text);
}
html[data-surface-library-card="sticker-card"] .lib.rc .rcard .rcgenre {
  background: var(--bk-role-brand);
  color: var(--bk-role-brand-deep);
}
html[data-surface-library-card="sticker-card"] .lib.rc .rcard .rcbody .rfoot {
  --stage-text-dim: #514051;
}
